INSERT INTO question_bank (subject, university, question, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
('biology','ALL','Which organelle is responsible for ATP synthesis in eukaryotic cells?','Mitochondria','Ribosomes','Golgi apparatus','Endoplasmic reticulum','A','Mitochondria are the sites of oxidative phosphorylation (ATP synthesis via electron transport chain).'),
('biology','ALL','In meiosis, crossing over occurs during:','Prophase I','Prophase II','Metaphase I','Anaphase I','A','Crossing over (chiasmata formation) occurs during Prophase I of meiosis when homologous chromosomes pair up (synapsis).'),
('biology','ALL','Which nitrogenous base is found in RNA but NOT in DNA?','Uracil','Thymine','Adenine','Guanine','A','RNA contains Uracil instead of Thymine. Both share Adenine, Guanine, and Cytosine.'),
('biology','ALL','The enzyme that unwinds the DNA double helix during replication is:','Helicase','DNA polymerase','Primase','Ligase','A','Helicase breaks hydrogen bonds between base pairs to unwind and separate DNA strands at the replication fork.'),
('biology','ALL','In the ABO blood group system, which genotype is universal donor?','OO','AB','AO','BO','A','Blood group O (genotype OO or ii) has no antigens → red cells accepted by all blood groups → universal donor.'),
('biology','ALL','Which structure connects muscle to bone?','Tendon','Ligament','Cartilage','Synovial membrane','A','Tendons are tough fibrous connective tissue connecting muscles to bones. Ligaments connect bone to bone.'),
('biology','ALL','The powerhouse of the cell is the mitochondrion. Its inner membrane contains:','Cristae','Matrix','Outer membrane','Intermembrane space','A','Cristae are folds of the inner mitochondrial membrane that house ATP synthase and ETC complexes.'),
('biology','ALL','Which hormone is responsible for the "fight or flight" response?','Adrenaline (epinephrine)','Insulin','Glucagon','Thyroxine','A','Adrenaline is secreted by the adrenal medulla during stress, triggering fight-or-flight responses.'),
('biology','ALL','In photosynthesis, where does the light-dependent reaction occur?','Thylakoid membrane','Stroma','Cytoplasm','Matrix','A','Light-dependent reactions occur in thylakoid membranes where photosystems I and II are located.'),
('biology','ALL','What is the term for the movement of water from high to low water potential across a semi-permeable membrane?','Osmosis','Diffusion','Active transport','Facilitated diffusion','A','Osmosis: net movement of water molecules down their water potential gradient across a selectively permeable membrane.'),
('biology','ALL','Which blood cells produce antibodies?','B lymphocytes (plasma cells)','T lymphocytes','Macrophages','Neutrophils','A','B lymphocytes differentiate into plasma cells which secrete antibodies (immunoglobulins).'),
('biology','ALL','The Calvin cycle produces:','Glyceraldehyde-3-phosphate (G3P)','Glucose directly','ATP only','NADPH only','A','The Calvin cycle (light-independent reactions) fixes CO₂ to produce G3P, which is used to synthesise glucose.'),
('biology','ALL','In a dihybrid cross between AaBb × AaBb, the phenotypic ratio for two independently assorting genes is:','9:3:3:1','1:2:1','3:1','1:1:1:1','A','Mendel''s dihybrid ratio: 9 A_B_ : 3 A_bb : 3 aaB_ : 1 aabb = 9:3:3:1.'),
('biology','ALL','Which enzyme cuts DNA at specific recognition sequences?','Restriction endonuclease','Ligase','Helicase','Polymerase','A','Restriction endonucleases cut DNA at specific palindromic sequences — key tools in genetic engineering.'),
('biology','ALL','The process by which cells engulf large particles by forming vesicles from cell membrane is called:','Phagocytosis','Pinocytosis','Exocytosis','Osmosis','A','Phagocytosis: cell engulfs solid particles/microorganisms into phagosomes (e.g., macrophages engulfing bacteria).'),
('biology','ALL','Which part of the brain controls balance and coordination of movement?','Cerebellum','Cerebrum','Medulla oblongata','Hypothalamus','A','Cerebellum coordinates voluntary movements, balance, and posture.'),
('biology','ALL','What is the role of NAD⁺ in cellular respiration?','Electron carrier (oxidising agent)','Energy source','Carbon dioxide carrier','Enzyme','A','NAD⁺ accepts electrons and protons to become NADH, serving as an electron carrier in glycolysis and Krebs cycle.'),
('biology','ALL','In the nephron, where does most reabsorption of glucose and amino acids occur?','Proximal convoluted tubule','Loop of Henle','Distal convoluted tubule','Collecting duct','A','The PCT reabsorbs ~65% of filtrate, all glucose, all amino acids, via active transport.'),
('biology','ALL','The end products of aerobic respiration are:','CO₂, H₂O, and ATP','CO₂ and lactic acid','Ethanol and CO₂','ATP and water only','A','Aerobic respiration: C₆H₁₂O₆+6O₂ → 6CO₂+6H₂O+ATP (38 ATP maximum).'),
('biology','ALL','Which type of mutation involves the addition or removal of a nucleotide, shifting the reading frame?','Frameshift mutation','Point mutation','Silent mutation','Missense mutation','A','Insertions or deletions of nucleotides cause frameshift mutations — all codons downstream are altered.'),
('biology','ALL','Which hormone stimulates the conversion of glycogen to glucose in the liver?','Glucagon','Insulin','Cortisol','ADH','A','Glucagon (from alpha cells of pancreas) activates glycogenolysis when blood glucose is low.'),
('biology','ALL','The fluid mosaic model of cell membranes was proposed by:','Singer and Nicolson','Watson and Crick','Darwin and Wallace','Schleiden and Schwann','A','Singer and Nicolson (1972) proposed the fluid mosaic model: phospholipid bilayer with embedded proteins.'),
('biology','ALL','In ecological succession, the pioneer community on bare rock is usually:','Lichens','Mosses','Grasses','Shrubs','A','Lichens (symbiosis of algae and fungi) are the first colonisers on bare rock, breaking it down to form soil.'),
('biology','ALL','Which type of symmetry do echinoderms display as adults?','Pentaradial symmetry','Bilateral symmetry','Radial symmetry','No symmetry','A','Adult echinoderms (e.g., starfish) have 5-fold (pentaradial) symmetry, though larvae are bilaterally symmetrical.'),
('biology','ALL','The role of the corpus luteum in pregnancy is to secrete:','Progesterone','Oestrogen only','FSH','LH','A','Corpus luteum secretes progesterone (and some oestrogen) to maintain uterine lining during early pregnancy.'),
('biology','ALL','Which vector transmits malaria (Plasmodium)?','Female Anopheles mosquito','Male Anopheles mosquito','Aedes mosquito','Culex mosquito','A','Only female Anopheles mosquitoes transmit Plasmodium (requires blood meal for egg development).'),
('biology','ALL','In the carbon cycle, decomposers play what role?','Breaking down organic matter, releasing CO₂','Fixing atmospheric CO₂','Producing oxygen','Forming limestone','A','Decomposers (fungi, bacteria) mineralise dead organic matter, releasing CO₂ back to atmosphere.'),
('biology','ALL','Which part of a flowering plant contains the male gametophyte?','Pollen grain','Ovule','Style','Stigma','A','Pollen grain is the male gametophyte, producing sperm cells for fertilisation.'),
('biology','ALL','How many chromosomes does a human somatic cell contain?','46','23','92','48','A','Human somatic (body) cells are diploid with 46 chromosomes (23 pairs). Gametes have 23 (haploid).'),
('biology','ALL','Which process in nitrogen cycle converts ammonia to nitrites?','Nitrification by Nitrosomonas','Denitrification','Nitrogen fixation','Ammonification','A','Nitrosomonas bacteria oxidise NH₃ → NO₂⁻ (nitrites). Nitrobacter converts NO₂⁻ → NO₃⁻.'),
('biology','ALL','The transport of oxygen by haemoglobin is mainly determined by:','Partial pressure of oxygen','Temperature only','CO₂ concentration only','pH only','A','Oxygen-haemoglobin dissociation curve is primarily determined by PO₂ (partial pressure of O₂).'),
('biology','ALL','What is the function of the acrosome in a sperm cell?','Contains enzymes to penetrate the egg','Provides energy for movement','Carries genetic material','Maintains membrane integrity','A','Acrosome contains hydrolytic enzymes (acrosin, hyaluronidase) released during acrosomal reaction to penetrate egg.'),
('biology','ALL','Which type of natural selection favours the average phenotype?','Stabilising selection','Directional selection','Disruptive selection','Sexual selection','A','Stabilising selection removes extremes, favouring the average phenotype (e.g., human birth weight).'),
('biology','ALL','The phenomenon where one gene masks the expression of another is called:','Epistasis','Dominance','Codominance','Linkage','A','Epistasis: one gene (epistatic) masks/suppresses phenotypic expression of another gene (hypostatic).'),
('biology','ALL','Which organelle processes and packages proteins for secretion?','Golgi apparatus','Rough ER','Smooth ER','Lysosome','A','Golgi apparatus receives proteins from ER, modifies, sorts, and packages them into vesicles for secretion.'),
('biology','ALL','In the electron transport chain, the final electron acceptor is:','Oxygen','NADH','CO₂','FAD','A','Oxygen is the terminal electron acceptor in aerobic respiration; electrons combine with O₂ and H⁺ to form water.'),
('biology','ALL','Which layer of the skin contains melanocytes?','Stratum basale (germinativum)','Stratum corneum','Stratum spinosum','Dermis','A','Melanocytes are located in the stratum basale (deepest layer of epidermis), producing melanin pigment.'),
('biology','ALL','Which of the following is a non-specific defence mechanism against pathogens?','Fever and inflammation','Antibody production','T-cell activation','Memory cell formation','A','Fever, inflammation, phagocytosis are non-specific (innate) immune responses — not targeted to specific antigens.'),
('biology','ALL','The process by which mRNA sequence is decoded to produce a specific amino acid sequence is:','Translation','Transcription','Replication','Splicing','A','Translation occurs at ribosomes where tRNA molecules deliver amino acids according to mRNA codons.'),
('biology','ALL','Which organism is used as indicator of water pollution by sewage?','Escherichia coli','Plasmodium','Aedes','Artemia','A','E. coli (coliform bacteria) indicates faecal contamination of water — used as biological indicator.'),
('biology','ALL','The type of immunity acquired after vaccination is:','Active artificial immunity','Passive natural immunity','Active natural immunity','Passive artificial immunity','A','Vaccine introduces antigens → body produces own antibodies → active (own response), artificial (man-made vaccine).'),
('biology','ALL','In Hardy-Weinberg equilibrium, if allele frequency p=0.6 and q=0.4, frequency of heterozygotes is:','0.48','0.36','0.16','0.24','A','Heterozygote frequency=2pq=2×0.6×0.4=0.48.'),
('biology','ALL','The part of the chloroplast where the Calvin cycle occurs is:','Stroma','Thylakoid','Granum','Inner membrane','A','The Calvin cycle (CO₂ fixation by RuBisCO) takes place in the stroma of chloroplasts.'),
('biology','ALL','Which type of feeding relationship describes a barnacle living on a whale without harming or helping it?','Commensalism','Mutualism','Parasitism','Competition','A','Commensalism: one organism benefits (+), the other is unaffected (0). Barnacle benefits, whale is unaffected.'),
('biology','ALL','The term "diploid" means the cell contains:','Two sets of chromosomes','One set of chromosomes','Four sets of chromosomes','Three sets of chromosomes','A','Diploid (2n): two complete sets of homologous chromosomes (one from each parent).'),
('biology','ALL','Which mineral is essential for the activation of thyroxine production?','Iodine','Iron','Calcium','Phosphorus','A','Iodine is incorporated into thyroxine (T₄) and triiodothyronine (T₃) by the thyroid gland.'),
('biology','ALL','What is the function of helper T-cells in the immune response?','Activating B-cells and cytotoxic T-cells','Directly killing pathogens','Producing antibodies','Engulfing pathogens','A','CD4+ helper T-cells release cytokines that activate B-cells (antibody production) and cytotoxic T-cells.'),
('biology','ALL','In plant cells, the structure that provides rigidity and prevents over-expansion is:','Cell wall','Cell membrane','Vacuole','Chloroplast','A','The cellulose cell wall provides mechanical support and rigidity, preventing lysis during osmotic water uptake.'),
('biology','ALL','Which structure in the mitochondrion houses the Krebs cycle enzymes?','Matrix','Inner membrane','Outer membrane','Intermembrane space','A','The mitochondrial matrix contains Krebs cycle enzymes and mitochondrial DNA.'),
('biology','ALL','What is the Bohr effect?','Decrease in oxygen affinity of Hb with increasing CO₂/decreasing pH','Increase in oxygen affinity with increasing CO₂','Binding of CO₂ to haem group','Release of oxygen when pH increases','A','Bohr effect: low pH (high CO₂/H⁺ in tissues) decreases Hb''s O₂ affinity, facilitating O₂ release to tissues.'),
('biology','ALL','Which of the following is a feature of C4 plants that makes them more efficient in hot conditions?','They concentrate CO₂ around RuBisCO in bundle sheath cells','They have more chlorophyll','They open stomata at night','They lack photorespiration entirely','A','C4 plants fix CO₂ first into 4C oxaloacetate in mesophyll, transport to bundle sheath where CO₂ is concentrated for Calvin cycle.'),
('biology','ALL','The chemical that carries the genetic code from the nucleus to the ribosome is:','mRNA','tRNA','rRNA','DNA','A','Messenger RNA (mRNA) carries the genetic information from DNA in the nucleus to ribosomes in the cytoplasm.'),
('biology','ALL','Which disease is caused by Trypanosoma brucei?','Sleeping sickness (African trypanosomiasis)','Malaria','Leishmaniasis','Bilharzia','A','Trypanosoma brucei causes African sleeping sickness, transmitted by tsetse fly (Glossina).'),
('biology','ALL','The law of segregation states that:','Alleles separate during gamete formation','Genes on different chromosomes assort independently','One allele is always dominant','Genes are located on chromosomes','A','Mendel''s first law: paired alleles segregate during meiosis so each gamete receives only one allele of each gene.'),
('biology','ALL','What is the term for the point where two neurons communicate?','Synapse','Node of Ranvier','Axon terminal','Myelin sheath','A','A synapse is the junction between neurons where neurotransmitters are released from presynaptic to postsynaptic membrane.'),
('biology','ALL','In which phase of mitosis do chromosomes line up at the cell equator?','Metaphase','Prophase','Anaphase','Telophase','A','During metaphase, chromosomes are aligned at the metaphase plate (cell equator) attached to spindle fibres.'),
('biology','ALL','Which of the following is a vestigial organ in humans?','Appendix','Pancreas','Spleen','Thyroid gland','A','The appendix is considered vestigial — a remnant of a larger caecum used for cellulose digestion in ancestors.'),
('biology','ALL','What is the functional unit of the kidney?','Nephron','Glomerulus','Ureter','Collecting duct','A','The nephron (including glomerulus, Bowman''s capsule, tubules) is the structural and functional unit of the kidney.'),
('biology','ALL','Which pigment is responsible for the red colour of red blood cells?','Haemoglobin','Myoglobin','Cytochrome','Carotenoid','A','Haemoglobin (with iron-containing haem group) gives red blood cells their characteristic red colour.'),
('biology','ALL','The process by which plants lose water through their leaves is called:','Transpiration','Guttation','Evaporation','Translocation','A','Transpiration is the loss of water vapour through stomata and cuticle of leaves, driven by evaporation.'),
('biology','ALL','Which type of tissue connects different parts of the body and provides support?','Connective tissue','Epithelial tissue','Muscle tissue','Nervous tissue','A','Connective tissue (bone, cartilage, blood, adipose) supports, connects, and separates tissues and organs.'),
('biology','ALL','In what form is glucose stored in the liver?','Glycogen','Starch','Cellulose','Sucrose','A','Excess glucose is converted to glycogen in the liver (glycogenesis) under insulin influence.'),
('biology','ALL','Which molecules carry amino acids to the ribosome during translation?','tRNA','mRNA','rRNA','snRNA','A','Transfer RNA (tRNA) has anticodon that matches mRNA codons and carries the corresponding amino acid to ribosome.'),
('biology','ALL','What is the role of the placenta?','Exchange of nutrients, gases, and waste between mother and foetus','Production of foetal blood cells','Secretion of amniotic fluid','Protection of foetus from shock','A','Placenta facilitates gas exchange (O₂, CO₂), nutrient transfer, and waste removal between maternal and foetal blood.'),
('biology','ALL','Which hormone triggers ovulation in the menstrual cycle?','LH surge','FSH','Oestrogen alone','Progesterone','A','A surge in LH (luteinising hormone) around day 14 triggers ovulation in a 28-day menstrual cycle.'),
('biology','ALL','Which part of the brain regulates body temperature, hunger, and thirst?','Hypothalamus','Cerebellum','Thalamus','Pituitary gland','A','The hypothalamus is the main homeostatic regulatory centre controlling temperature, hunger, thirst, and circadian rhythms.'),
('biology','ALL','The Hardy-Weinberg principle assumes:','Random mating, no mutation, no selection, no migration, large population','Small population size','Frequent mutation','Non-random mating','A','H-W equilibrium requires: random mating, no mutation, no natural selection, no migration, infinitely large population.'),
('biology','ALL','Which type of natural killer cells directly destroy cells infected by viruses?','Cytotoxic T-cells (CD8+)','B-cells','Plasma cells','Helper T-cells','A','CD8+ cytotoxic T-lymphocytes recognise and kill virus-infected cells via perforin/granzyme mechanism.'),
('biology','ALL','In aerobic respiration, how many ATP molecules are produced from one molecule of NADH via oxidative phosphorylation?','2.5 ATP','3 ATP','2 ATP','1 ATP','A','Modern estimates: each NADH yields ~2.5 ATP (older textbooks said 3). Each FADH₂ yields ~1.5 ATP.'),
('biology','ALL','Which type of reproduction produces offspring genetically identical to the parent?','Asexual reproduction','Sexual reproduction','Parthenogenesis','Conjugation','A','Asexual reproduction (binary fission, budding, cloning) produces genetically identical offspring (clones).'),
('biology','ALL','Which enzyme catalyses the fixation of CO₂ in the Calvin cycle?','RuBisCO','ATP synthase','NADP reductase','Phosphoglycerate kinase','A','Ribulose-1,5-bisphosphate carboxylase/oxygenase (RuBisCO) catalyses CO₂ + RuBP → 2 molecules of 3-PGA.'),
('biology','ALL','The human immune system''s ability to remember pathogens it has previously encountered is due to:','Memory cells','Phagocytes','Natural killer cells','Complement proteins','A','Memory B and T cells persist after initial exposure, allowing faster and stronger secondary immune response.'),
('biology','ALL','Which metabolic pathway occurs in the cytoplasm and does not require oxygen?','Glycolysis','Krebs cycle','Oxidative phosphorylation','Beta-oxidation','A','Glycolysis occurs in cytoplasm and is anaerobic: glucose → 2 pyruvate + 2 ATP + 2 NADH.'),
('biology','ALL','What determines the sex of offspring in humans?','Sex chromosome from sperm (X or Y)','Sex chromosome from egg (always X)','Maternal hormone levels','Paternal age','A','Egg always contributes X chromosome; sperm contributes either X (girl) or Y (boy) → father determines sex.'),
('biology','ALL','Which type of evolution occurs when two unrelated species independently evolve similar traits?','Convergent evolution','Divergent evolution','Co-evolution','Adaptive radiation','A','Convergent evolution: unrelated lineages evolve similar adaptations in response to similar environmental pressures.'),
('biology','ALL','In the nitrogen cycle, which organisms are responsible for nitrogen fixation?','Rhizobium, Azotobacter, cyanobacteria','Nitrosomonas','Pseudomonas','Nitrobacter','A','Nitrogen-fixing bacteria (Rhizobium in legume root nodules, free-living Azotobacter, cyanobacteria) convert N₂→NH₃.'),
('biology','ALL','A population bottleneck leads to:','Reduced genetic diversity','Increased genetic diversity','Increased population size','Decreased selection pressure','A','Bottleneck drastically reduces population size → random loss of alleles → reduced genetic variation (genetic drift).'),
('biology','ALL','Which biomolecule forms the structural framework of DNA?','Deoxyribose-phosphate backbone','Adenine-thymine pairs','Guanine-cytosine pairs','Hydrogen bonds','A','The deoxyribose sugar-phosphate groups form the alternating backbone of DNA; bases project inward.'),
('biology','ALL','The release of a secondary oocyte from the ovary is triggered by:','LH surge at mid-cycle','FSH only','Progesterone peak','Oestrogen decrease','A','A mid-cycle surge of LH causes the dominant follicle to rupture, releasing the secondary oocyte (ovulation).'),
('biology','ALL','Which structural protein forms the cytoskeleton?','Actin and tubulin','Collagen','Keratin','Myosin','A','Microfilaments (actin) and microtubules (tubulin) are key components of the cytoskeleton providing cell shape and movement.'),
('biology','ALL','In which stage of cellular respiration is the most ATP produced?','Oxidative phosphorylation (ETC)','Glycolysis','Krebs cycle','Pyruvate oxidation','A','~34 ATP from oxidative phosphorylation (ETC) vs 2 from glycolysis and 2 from Krebs cycle.'),
('biology','ALL','What is the role of the lymphatic system?','Return interstitial fluid to blood and transport fats','Carry oxygenated blood','Filter blood in spleen only','Produce red blood cells','A','Lymphatic system returns excess tissue fluid to bloodstream and transports dietary fats (chylomicrons) from gut.'),
('biology','ALL','Which statement correctly describes active transport?','Movement against concentration gradient using ATP','Movement along concentration gradient','Does not require energy','Uses protein channels without ATP','A','Active transport requires carrier proteins and ATP to move molecules against their concentration gradient.'),
('biology','ALL','The centriole plays a crucial role in:','Formation of spindle fibres during cell division','Protein synthesis','ATP production','Photosynthesis','A','Centrioles organise the mitotic spindle (microtubules) during cell division in animal cells.'),
('biology','ALL','Which of the following is a difference between mitosis and meiosis?','Meiosis produces haploid cells; mitosis produces diploid cells','Meiosis is faster than mitosis','Mitosis involves crossing over','Both produce the same number of cells','A','Meiosis: 4 haploid (n) cells with crossing over and 2 divisions; Mitosis: 2 diploid (2n) cells, no crossing over.'),
('biology','ALL','What type of bond holds the two strands of DNA together?','Hydrogen bonds between complementary bases','Covalent bonds','Ionic bonds','Phosphodiester bonds','A','Hydrogen bonds (A-T: 2 H-bonds; G-C: 3 H-bonds) hold the two antiparallel DNA strands together.'),
('biology','ALL','Which organ in the body is responsible for producing bile?','Liver','Gallbladder','Pancreas','Small intestine','A','Bile is produced by hepatocytes in the liver, stored in gallbladder, and released into duodenum for fat emulsification.'),
('biology','ALL','The theory of evolution by natural selection was proposed by:','Charles Darwin and Alfred Russel Wallace','Gregor Mendel','Jean-Baptiste Lamarck','Thomas Malthus','A','Darwin and Wallace independently proposed natural selection (1858), published simultaneously to the Linnean Society.'),
('biology','ALL','Which type of muscle is found in the walls of internal organs?','Smooth muscle','Skeletal muscle','Cardiac muscle','Striated muscle','A','Smooth (visceral) muscle is involuntary, non-striated, found in gut, bladder, blood vessels, etc.'),
('biology','ALL','The function of lysosomes in a cell is:','Intracellular digestion using hydrolytic enzymes','Protein synthesis','Energy production','Cell division','A','Lysosomes contain hydrolytic enzymes (proteases, lipases, nucleases) for breaking down cellular waste and foreign particles.'),
('biology','ALL','Which phylum contains organisms with jointed appendages and an exoskeleton?','Arthropoda','Mollusca','Annelida','Echinodermata','A','Arthropods (insects, crustaceans, arachnids) have chitinous exoskeleton and jointed appendages.'),
('biology','ALL','In a food chain, the amount of energy transferred from one trophic level to the next is approximately:','10%','50%','90%','25%','A','The 10% rule: only ~10% of energy at one trophic level is transferred to the next; 90% is lost as heat.'),
('biology','ALL','Which process converts pyruvate to acetyl-CoA?','Pyruvate oxidation (link reaction)','Glycolysis','Krebs cycle','Beta-oxidation','A','Pyruvate decarboxylation (link reaction) in mitochondrial matrix: pyruvate + CoA → acetyl-CoA + CO₂ + NADH.'),
('biology','ALL','The structure responsible for gas exchange in fish is the:','Gill','Lung','Spiracle','Skin','A','Fish gills are adapted for aquatic gas exchange: large surface area, thin epithelium, counter-current flow.'),
('biology','ALL','What does the term "allele" mean?','Alternative forms of a gene at the same locus','Two identical genes','A single gene on one chromosome','A gene on the X chromosome only','A','Alleles are different versions of a gene, located at the same locus on homologous chromosomes.');
